$(document).ready(function(){$(".ghbtn").each(function(){var t=$(this),a=t.attr("user"),r=t.attr("repo");a&&r&&$.ajax({type:"GET",url:"https://api.github.com/repos/"+encodeURIComponent(a)+"/"+encodeURIComponent(r),tryCount:0,retryLimit:3,async:!0,dataType:"json",success:function(a){var r="number"==typeof a.stargazers_count?a.stargazers_count:"–",e="number"==typeof a.forks_count?a.forks_count:"–";t.children(".star").html('<i class="fa fa-star"></i> '+r),t.children(".fork").html('<i class="fa fa-code-fork"></i> '+e)},error:function(a,r){this.tryCount=(this.tryCount||0)+1,("timeout"===r||a.status>=500&&this.tryCount<=this.retryLimit)?$.ajax(this):(t.children(".star").html('<i class="fa fa-star"></i> –'),t.children(".fork").html('<i class="fa fa-code-fork"></i> –'))}})})});
